    private static string TwoTurnMove(RubyWikiMove move)
    {
        string position = move.Id switch { 91 => "unter der Erde", 291 => "unter Wasser", _ => "in der Luft" };
        string description = $"Der Anwender ist in der ersten Runde {position} und meidet viele Angriffe. Er greift in der zweiten Runde an.";
        return move.Id == 340 ? $"{description} Kann das Ziel paralysieren ({move.Chance} %)." : description;
    }
